// Arma un mensaje corto y legible con los datos del error.
// El Error Trigger trae dos formas posibles:
//  A) falló un nodo durante la ejecución -> viene "execution"
//  B) falló el propio trigger del workflow -> viene "trigger" (sin execution)
const d = $('Error Trigger').first().json;
const enTrigger = !d.execution;
const err = enTrigger ? (d.trigger?.error ?? {}) : (d.execution?.error ?? {});
const ahora = DateTime.now().setZone('America/Montevideo').toFormat('dd/MM/yyyy HH:mm');
const nodo = d.execution?.lastNodeExecuted ?? err.node?.name ?? 'trigger';
const lineas = [
  '🚨 Brújula: falló un workflow',
  '',
  'Workflow: ' + (d.workflow?.name ?? 'desconocido'),
  'Nodo: ' + nodo,
  'Error: ' + String(err.message ?? 'sin mensaje').slice(0, 600),
  'Cuándo: ' + ahora,
];
if (err.description) lineas.push('Detalle: ' + String(err.description).slice(0, 400));
if (d.execution?.url) lineas.push('', 'Ver ejecución: ' + d.execution.url);
if (enTrigger) lineas.push('', '(Falló el disparador: no llegó a crearse una ejecución.)');
// Chat del staff: sale de staff_chat_id en la hoja config. Si la hoja no respondió
// (muchas fallas vienen justamente de Google Sheets), se usa el chat de respaldo.
const RESPALDO = '8786367981';
let chat = '';
try {
  const fila = $('Leer config').all().map(function (i) { return i.json; }).find(function (r) { return r && r.clave === 'staff_chat_id'; });
  chat = fila ? String(fila.valor || '').trim() : '';
} catch (e) { chat = ''; }
const chat_id = /^-?\d+$/.test(chat) ? chat : RESPALDO;
return [{ json: { texto: lineas.join('\n').slice(0, 3900), workflow: d.workflow?.name ?? '', nodo, chat_id } }];
